// PostInstanceAction calls POST /v2/publicCloud/project/{projectId}/compute/instance/{instanceId}/action: Run an instance action
//
// Perform an instance action.
//
// Imperative endpoint for power and lifecycle actions on an instance. This is the one place such
// imperative operations live. Distinct from the declarative `PUT` on the instance, which reconciles
// desired state from a `targetSpec` diff. Actions are asynchronous: the instance transitions
// through the relevant transient state and the response echoes the instance. Poll `GET
// .../instance/{instanceId}` until `resourceStatus` is `READY` and `currentTasks` is empty.
//
// Action `type`
//
// The `type` field selects the operation:
//
//   - `REBOOT` — reboot the instance (`parameters.hard` chooses a hard vs. soft reboot).
//   - `START` / `STOP` — power the instance on / off.
//   - `SHELVE` / `UNSHELVE` — shelve the instance (freeing hypervisor resources) and restore it.
//   - `PAUSE` / `UNPAUSE` — freeze a running instance in the memory of the host, and unfreeze it.
//   - `SUSPEND` / `RESUME` — save the memory state of a running instance to disk and stop it, and
//     restore it.
//   - `RESCUE` / `UNRESCUE` — boot into rescue mode (optionally from `parameters.imageId`) and
//     return to normal boot.
//   - `LOCK` / `UNLOCK` — lock the instance against accidental actions / modifications, and unlock
//     it.
//
// Optimistic concurrency (`checksum`)
//
// The `checksum` is optional. When you send it, it must match the current server-side value or the
// action is rejected with a checksum-mismatch error. Re-`GET` and retry. When you omit it (or send
// an empty string), the check is skipped and the action is forced (last-write-wins). An action
// requested while the instance is in an incompatible state is rejected with
// `ResourceInInvalidState`.
//
// Arguments:
//   - projectID: Project ID
//   - instanceID: Instance ID
//   - body: the request body
//
// Requires the IAM action publicCloudProject:apiovh:instance/runAction.
func (s *Service) PostInstanceAction(ctx context.Context, projectID string, instanceID string, body PublicCloudInstanceInstanceActionRequest) (*PublicCloudInstanceInstance, error) {
	return ovh.Call[*PublicCloudInstanceInstance](ctx, s.c, &ovh.Request{Method: http.MethodPost, Path: ovh.Path("/v2/publicCloud/project/{projectId}/compute/instance/{instanceId}/action", "projectId", projectID, "instanceId", instanceID), Body: body})
}
